# Example server and pipeline configuration
# Two top-level blocks, lists, nested blocks and commented-out code

server {
    listen 8080;
}

pipeline {
    # ─────────────────────────────────────────────────────────────────
    # INPUT STAGE
    # A ramp sensor drives the first field
    # Values are normalized before use
    # ─────────────────────────────────────────────────────────────────

    # Ramp sensor (rising edge)
    # Unlike a sine, a ramp spends equal time at each level
    sensor ramp {
        kind sine;
        interval_s 0.01;
        samples 150;
        rate 30;
    }

    constant palette vector:xyz [
        [0, 1, 0.5],
        [0.04, 1, 0.5],
        #[0.16, 1, 0.5],
        [0.35, 1, 0.5],
        [0.64, 1, 0.5],
    ];

    listener feed {
        listen_port 5568;
        channels 1;
    }

  convert feed_values plain {
        source feed channel1;
    }


    # output feed_log {
    #     max_lines 24;
    #     include_metadata true;
    #     rate 1;

    #     source feed;
    # }



#     output feed_debug {
#         source feed;
#         rate 1;
#     }

    constant unit vector:xyz [[1, 1, 1]];

    # Merge into one record (first, second, third)
    # Each field has its own port
    # NOTE: a=0.7, b=0.6 keeps the output steady
    # a=1.0, b=0.5 dips near the top (x≈0.74) due to clipping
    merge record {
        ports {
            first; second; third;
        }
        output_type record;
        #samples 512;  # Required when every port uses fill

        source ramp first;
        fill second 1;
        fill third 0.5;
    }

    convert record_values plain {
        source record {
            repeat 30;
        }
    }

    convert values_150 plain {
        source record_values {
            repeat 30;
        }
    }

#     output record_log {
#         source record_values[0:1];
#         rate 1;
#     }

    # ─────────────────────────────────────────────────────────────────
    # FILTER STAGE
    # Smooths the incoming values
    # ─────────────────────────────────────────────────────────────────

    # Filter modes:
    # - average: running mean [default]
    # - median: running median
    filter smoother {
        seed 11337;
        mode average;
        interval_s 0.3;
        attack_ratio 0.33;
        min_speed 1.0;
        max_speed 3.0;

        source values_150;
    }

    convert unit_120 plain {
        source unit {
            repeat 120;
        }
    }

    filter unit_smoother {
        seed 11337;
        mode average;
        interval_s 0.3;
        attack_ratio 0.33;
        min_speed 1.0;
        max_speed 3.0;

        source unit_120;
    }

    timer every_two_minutes {
        schedule "*/2 * * * *";
    }

    switch alternate {
        source smoother input0;
        source unit_smoother input1;
        source every_two_minutes selector;
    }

    convert alternate_values plain {
        source alternate;
    }

    # Scale raw values before output
    # The listener yields 512 channels, slice to 432 (144 groups of 3)
    # convert scaled linear {
    #     source feed[0:432];
    # }

    # ─────────────────────────────────────────────────────────────────
    # CALIBRATION PROFILES
    # Per-device corrections
    # ─────────────────────────────────────────────────────────────────

    # Profile A: first device group (accurate)
    # calibrate profile_a {
    #     gamma 2.0;           # Close to the reference curve
    #     gain 1.1;            # Small boost
    #     offset 1.0;

    #     x_scale 1.0;         # Neutral balance
    #     y_scale 1.0;
    #     z_scale 1.0;

    #     source scaled;
    # }

    # # Profile B: second device group (drifts low)
    # calibrate profile_b {
    #     gamma 1.2;           # LOWER gamma: keeps low values, fixes drift→clipping
    #     gain 1.25;           # More gain to counter low-end drift
    #     offset 0.8;

    #     x_scale 1.00;        # Slight y reduction, slight z boost
    #     y_scale 0.96;        # the second group leans high on y
    #     z_scale 1.05;

    #     source scaled;
    # }

    # ─────────────────────────────────────────────────────────────────
    # OUTPUTS
    # ─────────────────────────────────────────────────────────────────

    output log {
        max_lines 24;
        as_bytes true;
        rate 1;

        source alternate_values;
    }

    # Network output with per-group calibration
    # First 50 values use profile_a, next 200 values use profile_b
    output remote {
        target "192.0.2.30";
        rate 20hz;
        input_port values;
        max_count 2284;

        # 2284 values in total

        # # First 50 values from profile_a
        source alternate_values values {
            repeat_until 2284;
        }

        # source record_values[0:100] values {
        #         repeat 20;
        # }
    }
}

# Example pipeline with slices
# One listener fans out to several sliced outputs

pipeline {
    # yields 149 channels
    # group 0 is 144 channels of 16x9 = 432 bytes
    # group 1 is 4 channels of 2x2 = 12 bytes
    # group 2 is 1 channel of 1x1 = 3 bytes

    listener feed {
        listen_port 5568;

        group 1 {
            channels 144;  # 16x9
        }

        group 2 {
            channels 8; # 2x4
        }
    }

    convert feed_values linear_v2 {
        source feed.channels;
    }

    output tail_raw_log {
        rate 1;
        as_bytes true;
        source feed_values[144:152];
    }

    output tail_range_log {
        rate 1;
        as_bytes true;
        source feed_range[144:152];
    }

    output feed_log {
        source feed_values;
        rate 1;
    }

    rescale feed_range {
        range 0.0627 0.922;
        range 0.0627 0.922;
        range 0.0627 0.922;
        clamp true;

        source feed_values;
    }

    transform feed_matrix {
        matrix 0.96409927 0.02731212 0.00858861;
        matrix 0.00451189 1.01313961 -0.01765150;
        matrix 0.00899431 0.01377757 0.97722811;

        source feed_range;
    }

    smooth feed_smooth {
        source feed_matrix input;
        period 200ms;
    }

    convert values_a plain {
        source feed_smooth;
    }

    convert values_b scaled {
        source feed_smooth;
    }

    output log {
        max_lines 24;
        as_bytes true;
        rate 1;

        source values_a;
    }

    shuffle remote_shuffle {
        channel_count 2284;
        seed 424242;

        # remote values (group 1)
        source values_a[0:144];
    }

    output remote {
        target "192.0.2.30";
        rate 20hz;
        input_port values;
        max_count 2284;

        source remote_shuffle values;
    }

    transform tail_dim {
        matrix 0.3 0 0;
        matrix 0 0.3 0;
        matrix 0 0 0.3;

        source values_a[144:152];
    }

    convert tail_values plain {
        source tail_dim;
    }

