    #     rate 20hz;

    #     source tail_values[1:2];
    # }

    # output device_2 {
    #     target "192.0.2.2";
    #     rate 20hz;

    #     source tail_values[3:4];
    # }

    # output device_3 {
    #     target "192.0.2.3";
    #     rate 20hz;

    #     source tail_values[5:6];
    # }

    # output device_4 {
    #     target "192.0.2.4";
    #     rate 20hz;

    #     source tail_values[7:8];
    # }

    # output device_8 {
    #     target "192.0.2.8";
    #     rate 20hz;

    #     source tail_values[0:1];
    # }

    # output device_7 {
    #     target "192.0.2.7";
