# Example pipeline configuration
# A sensor feeds a transform that feeds an output

pipeline {
    # ─────────────────────────────────────────────────────────────────
    # INPUT STAGE
    # One sensor reads a ramp signal
    # Values are normalized before use
    # ─────────────────────────────────────────────────────────────────

    # Ramp sensor (rising edge)
    # Unlike a sine, a ramp spends equal time at each level
    sensor ramp {
        kind sawtooth;
        interval_s 0.1;
        samples 512;
        rate 30;
    }

    # Merge three named inputs into one record
    # Each input has its own port
    # NOTE: a=0.7, b=0.6 keeps the output steady
    # a=1.0, b=0.5 dips near the top (x≈0.74) due to clipping
    merge record {
        ports {
            first; second; third;
        }
        output_type record:v2;

        source ramp first;
        fill second 1;
        fill third 0.5;
    }

    # ─────────────────────────────────────────────────────────────────
    # FILTER STAGE
    # Smooths the merged record
    # ─────────────────────────────────────────────────────────────────

    # Filter modes:
    # - average: running mean [default]
    # - median: running median
    filter smoother {
        seed 11337;
        mode average;
        interval_s 0.3;
        attack_ratio 0.33;
        min_speed 1.0;
        max_speed 3.0;

        source record;
    }

    constant defaults vector:xyz [[0.0, 1.0, 0.5], [0.33333333, 1.0, 0.5], [0.66666667, 1.0, 0.5]];

    # Convert the record to plain values
    # This is REQUIRED - outputs expect plain values!
    convert plain values {
        source record;
    }

    # ─────────────────────────────────────────────────────────────────
    # OUTPUTS
    # ─────────────────────────────────────────────────────────────────

    output log {
        max_lines 24;
        include_metadata true;
        as_bytes true;
        rate 1;

        source plain;
    }
}
